class TestStoreBreakdownData(UnitTestCase):

	def test_stores_json_on_doc(self):
		import json
		tax_data = _make_us_breakdown()
		doc = _make_doc()
		_store_breakdown_data(tax_data, doc)

		self.assertIsNotNone(doc.taxjar_breakdown_json)
