# ── Tax Breakdown: server-side HTML rendering (get_taxjar_breakdown_html) ──
# Same tax-break-up/table-bordered/table-hover markup as core ERPNext's Tax
# Breakup table and india_compliance's GST Breakup Table, rendered server-side
# via Jinja (templates/includes/taxjar_breakup.html) instead of built in JS.

class TestGetTaxjarBreakdownHtml(UnitTestCase):

	def test_no_json_shows_no_breakdown_message(self):
		doc = _make_doc()
		html = get_taxjar_breakdown_html(doc)
		self.assertIn("No TaxJar tax breakdown available", html)

	def test_invalid_json_falls_back_to_no_breakdown_message(self):
		doc = _make_doc()
		doc.taxjar_breakdown_json = "not json"
		html = get_taxjar_breakdown_html(doc)
		self.assertIn("No TaxJar tax breakdown available", html)

	def test_renders_table_with_core_erpnext_markup(self):
		"""Same skeleton as erpnext's itemised_tax_breakup.html /
		india_compliance's gst_breakup.html - and, unlike the old JS builder,
		no inline thead background overriding the default desk table theme."""
		tax_data = _make_us_breakdown()
		doc = _make_doc()
		_store_breakdown_data(tax_data, doc)
		html = get_taxjar_breakdown_html(doc)
		self.assertIn('class="tax-break-up"', html)
		self.assertIn("table-bordered", html)
		self.assertIn("table-hover", html)
		self.assertIn("Jurisdiction", html)
		self.assertNotIn("background-color", html)

	def test_output_has_no_newlines_or_tabs(self):
		"""Jinja's {% if/for %} control tags leave their surrounding blank
		lines/indentation in the rendered output; a Text Editor field renders
		that whitespace as real vertical gaps in the desk form (a large empty
		block above the table). Same fix india_compliance applies to its own
		gst_breakup_table render."""
		tax_data = _make_us_breakdown()
		doc = _make_doc()
		_store_breakdown_data(tax_data, doc)
		doc.taxjar_freight_taxable = 1
		html = get_taxjar_breakdown_html(doc)
		self.assertNotIn("\n", html)
		self.assertNotIn("\t", html)

	def test_jurisdiction_rendered_bold(self):
		tax_data = _make_us_breakdown()
		doc = _make_doc()
		_store_breakdown_data(tax_data, doc)
		html = get_taxjar_breakdown_html(doc)
		self.assertIn("<strong>State</strong>", html)
		self.assertIn("<strong>County</strong>", html)
		self.assertIn("<strong>Special</strong>", html)

	def test_no_usd_block_for_single_currency_doc(self):
		tax_data = _make_us_breakdown()
		doc = _make_doc()
		_store_breakdown_data(tax_data, doc)
		html = get_taxjar_breakdown_html(doc)
		self.assertNotIn("Tax Calculation (USD)", html)

	def test_usd_block_rendered_for_multi_currency_doc(self):
		tax_data = _make_us_breakdown()
		doc = _make_doc(currency="EUR")
		_store_breakdown_data(tax_data, doc, usd_rate=1.1)
		html = get_taxjar_breakdown_html(doc)
		self.assertIn("Tax Calculation (USD)", html)
		self.assertIn("Equivalent in Transaction Currency (EUR)", html)
		self.assertIn("multi-currency transaction", html)

	def test_pill_not_part_of_server_rendered_html(self):
		"""The shipping-taxability pill moved to its own plain-HTML field
		(taxjar_freight_taxable_html, rendered client-side by
		render_shipping_taxability in taxjar_utils.js) - a read-only Text
		Editor field boxes its whole content in a "like-disabled-input"
		background, which reads fine around the table but wrong around a
		standalone indicator pill sitting inside it."""
		tax_data = _make_us_breakdown()
		doc = _make_doc()
		_store_breakdown_data(tax_data, doc)
		doc.taxjar_freight_taxable = 1
		html = get_taxjar_breakdown_html(doc)
		self.assertNotIn("Are shipping charges taxable?", html)
		self.assertNotIn("indicator-pill", html)

	def test_jurisdiction_and_name_are_html_escaped(self):
		"""Defensive escaping of TaxJar-sourced jurisdiction/name text, same
		posture as the old JS's frappe.utils.escape_html() calls."""
		import json as _json
		tax_data = _make_us_breakdown()
		doc = _make_doc()
		_store_breakdown_data(tax_data, doc)
		data = _json.loads(doc.taxjar_breakdown_json)
		data["transaction"][0]["name"] = "<script>alert(1)</script>"
		doc.taxjar_breakdown_json = _json.dumps(data)
		html = get_taxjar_breakdown_html(doc)
		self.assertNotIn("<script>alert(1)</script>", html)
		self.assertIn("&lt;script&gt;", html)


# ── No tax charged: a reason in place of an empty breakdown ──
# TaxJar answers a non-taxable line (bottled water in Florida, say) with no
# jurisdiction rows and a 0% total. The table of nothing that rendered from
# that told the reader nothing; the form and the print format now say why.

def _zero_tax_doc(**fields):
	doc = _make_doc()
	doc.taxjar_has_nexus = 1
	doc.taxjar_customer_taxable = 1
	doc.taxjar_transaction_exempt = 0
	doc.taxjar_ship_to = "Miami, FL 33169"
	doc.taxjar_breakdown_json = json.dumps({
		"currency": "USD",
		"transaction": [],
		"totals": {"rate": 0.0, "amount_to_collect": 0.0, "taxable_amount": 0.0},
		"line_items": [{"id": "1", "tax_collectable": 0.0, "taxable_amount": 0.0,
		                "item_amount": 1000.0, "breakdown": []}],
	})
	for key, value in fields.items():
		setattr(doc, key, value)
	return doc


class TestZeroTaxState(UnitTestCase):

	def test_non_taxable_items_replace_the_empty_table(self):
		doc = _zero_tax_doc(taxjar_product_taxable="No")
		html = get_taxjar_breakdown_html(doc)
		self.assertIn(
			"None of the items are taxable in Miami, FL 33169, hence no taxes are charged.", html
		)
		self.assertNotIn("<table", html)

	# The breakdown and the invoice's grey source line both state the
	# exemption, and they used to word it differently - "The customer is exempt
	# from sales tax" here, "Customer is exempted from taxes" there. Both read
	# _exemption_reason() now, so one fact is stated one way.

	def test_exempt_customer_is_the_reason(self):
		doc = _zero_tax_doc(taxjar_customer_taxable=0, taxjar_product_taxable="No")
		html = get_taxjar_breakdown_html(doc)
		self.assertIn("Customer is exempted from taxes", html)

	def test_exempt_transaction_is_the_reason(self):
		doc = _zero_tax_doc(taxjar_transaction_exempt=1)
		html = get_taxjar_breakdown_html(doc)
		self.assertIn("Transaction is exempted from taxes", html)

	def test_a_reason_that_ends_in_a_full_stop_does_not_keep_it(self):
		"""EXPORT_NO_TAX_REASON stands alone everywhere else - the form's
		message strip prints it as it is - so it ends in a full stop. Joined to
		", hence no taxes are charged." that read "...transactions., hence".

		Print never showed it: an export takes the template's is_zero_tax
		branch, so the sentence reached the form alone.
		"""
		from taxjar_integration.taxjar_integration.taxjar_integration import EXPORT_NO_TAX_REASON

		# An export as the document really holds it: no nexus, so no calculation
		# and no stored breakdown, and the reason on taxjar_nexus_reason.
		doc = _make_doc()
		doc.taxjar_has_nexus = 0
		doc.taxjar_nexus_reason = EXPORT_NO_TAX_REASON
		doc.taxjar_breakdown_json = None
		html = get_taxjar_breakdown_html(doc)

		self.assertNotIn("., hence", html)
		self.assertIn("on export transactions, hence no taxes are charged.", html)

	def test_the_constant_itself_keeps_its_full_stop(self):
		"""Dropped from the constant instead, every standalone reader of it
		would lose one - the message strip, and the stored nexus reason."""
		from taxjar_integration.taxjar_integration.taxjar_integration import EXPORT_NO_TAX_REASON

		self.assertTrue(EXPORT_NO_TAX_REASON.endswith("."))

	def test_a_reason_with_no_full_stop_is_untouched(self):
		from taxjar_integration.taxjar_integration.taxjar_integration import _as_clause

		self.assertEqual(_as_clause("Nexus not configured for NJ"), "Nexus not configured for NJ")
		self.assertIsNone(_as_clause(None))
		self.assertEqual(_as_clause(""), "")

	def test_the_breakdown_and_the_invoice_word_it_the_same_way(self):
		"""One fact, one sentence, wherever it is shown."""
		from taxjar_integration.taxjar_integration.taxjar_integration import (
			_exemption_reason,
			get_taxjar_print_context,
		)

		doc = _zero_tax_doc(taxjar_transaction_exempt=1)
		self.assertIn(_exemption_reason(doc), get_taxjar_breakdown_html(doc))
		self.assertEqual(get_taxjar_print_context(doc).exemption_reason, _exemption_reason(doc))

	def test_taxable_items_with_no_tax_get_a_general_reason(self):
		doc = _zero_tax_doc(taxjar_product_taxable="Yes")
		html = get_taxjar_breakdown_html(doc)
		self.assertIn("No sales tax applies in Miami, FL 33169", html)

	def test_a_calculation_with_tax_still_shows_the_table(self):
		doc = _make_doc()
		doc.taxjar_has_nexus = 1
		_store_breakdown_data(_make_us_breakdown(), doc)
		html = get_taxjar_breakdown_html(doc)
		self.assertIn("<table", html)
		self.assertNotIn("hence no taxes are charged", html)

	def test_no_nexus_keeps_its_own_message(self):
		"""No breakdown JSON: the no-nexus path clears it (_clear_breakdown_data)."""
		doc = _zero_tax_doc(
			taxjar_has_nexus=0,
			taxjar_nexus_reason="Nexus not configured for NJ",
			taxjar_breakdown_json=None,
		)
		html = get_taxjar_breakdown_html(doc)
		self.assertIn("Nexus not configured for NJ, hence no taxes are charged.", html)
		self.assertNotIn("None of the items", html)


class TestTaxjarPrintContext(UnitTestCase):

	def test_no_taxable_items_is_the_zero_tax_reason(self):
		from taxjar_integration.taxjar_integration.taxjar_integration import get_taxjar_print_context

		context = get_taxjar_print_context(_zero_tax_doc(taxjar_product_taxable="No"))
		self.assertIn("None of the items are taxable", context.zero_tax_reason)

	def test_a_calculation_with_tax_gives_no_zero_tax_reason(self):
		from taxjar_integration.taxjar_integration.taxjar_integration import get_taxjar_print_context

		doc = _make_doc()
		doc.taxjar_has_nexus = 1
		doc.taxjar_customer_taxable = 1
		_store_breakdown_data(_make_us_breakdown(), doc)
		self.assertIsNone(get_taxjar_print_context(doc).zero_tax_reason)

	def _reason(self, customer_type=None, **fields):
		"""The exemption sentence for one document.

		customer_type is what the Customer's own master record holds. It is
		read only on the customer-exempt path, so the stub answers for that
		field alone and lets everything else reach the real frappe.db.
		"""
		from taxjar_integration.taxjar_integration.taxjar_integration import get_taxjar_print_context

		real = frappe.db.get_value

		def fake(doctype, *args, **kwargs):
			if doctype == "Customer" and args and args[1:2] == ("taxjar_exemption_type",):
				return customer_type
			return real(doctype, *args, **kwargs)

		with patch(f"{_TJ}.frappe.db.get_value", side_effect=fake):
			return get_taxjar_print_context(_zero_tax_doc(**fields)).exemption_reason

	# The customer is exempt whatever they buy. The type is on their master
	# record; Wholesale and Government are named, anything else reads plain.

	def test_a_wholesale_customer_is_named(self):
		self.assertEqual(
			self._reason("Wholesale", taxjar_customer_taxable=0),
			"Wholesale customer is exempted from taxes",
		)

	def test_a_government_customer_is_named(self):
		self.assertEqual(
			self._reason("Government", taxjar_customer_taxable=0),
			"Government customer is exempted from taxes",
		)

	def test_any_other_customer_exemption_reads_plain(self):
		"""Other, and a customer with no type at all."""
		for customer_type in ("Other", None, ""):
			with self.subTest(customer_type=customer_type):
				self.assertEqual(
					self._reason(customer_type, taxjar_customer_taxable=0),
					"Customer is exempted from taxes",
				)

	# This one transaction was marked exempt. Its type is on the document.

	def test_a_wholesale_transaction_is_named(self):
		self.assertEqual(
			self._reason(taxjar_transaction_exempt=1, taxjar_transaction_exemption_type="Wholesale"),
			"Wholesale transaction is exempted from taxes",
		)

	def test_a_government_transaction_is_named(self):
		self.assertEqual(
			self._reason(taxjar_transaction_exempt=1, taxjar_transaction_exemption_type="Government"),
			"Government transaction is exempted from taxes",
		)

	def test_any_other_transaction_exemption_reads_plain(self):
		self.assertEqual(
			self._reason(taxjar_transaction_exempt=1, taxjar_transaction_exemption_type="Other"),
			"Transaction is exempted from taxes",
		)

	def test_the_customer_is_not_read_when_the_transaction_is_the_exempt_one(self):
		"""A taxable customer with a marked transaction. The customer's own
		type says nothing about it, and the query is not worth making."""
		self.assertEqual(
			self._reason("Wholesale", taxjar_transaction_exempt=1),
			"Transaction is exempted from taxes",
		)

	def test_a_document_with_no_customer_reads_plain(self):
		"""get_value with a name of None reads the first row of the table
		rather than nothing, so the name is checked before the query."""
		self.assertEqual(
			self._reason("Wholesale", taxjar_customer_taxable=0, customer=None),
			"Customer is exempted from taxes",
		)

	def test_neither_comment_still_claims_per_line_taxability(self):
		"""The item rows carried a Taxable/Exempt tag until it was removed. The
		print format's own header and the hooks entry both still listed it
		among what they provide."""
		import os

		base = os.path.dirname(__file__)
		with open(os.path.normpath(os.path.join(
			base, "..", "..", "print_format", "us_sales_tax_(invoice,_dn,_cn)", "us_sales_tax_(invoice,_dn,_cn).html",
		))) as f:
			header = f.read().split("#}")[0]
		with open(os.path.normpath(os.path.join(base, "..", "..", "..", "hooks.py"))) as f:
			hooks = f.read()

		self.assertNotIn("per-line taxability, shipping", header)
		self.assertNotIn("per-line taxability and the no-tax reason", hooks)
		self.assertIn("get_taxjar_print_context", hooks)

	def test_the_template_reads_the_context_instead_of_the_database(self):
		"""The six sentences were Jinja branches, and one of them queried the
		Customer on every render for a value tj already carried."""
		import os

		path = os.path.normpath(os.path.join(
			os.path.dirname(__file__), "..", "..",
			"print_format", "us_sales_tax_(invoice,_dn,_cn)", "us_sales_tax_(invoice,_dn,_cn).html",
		))
		with open(path) as f:
			html = f.read()

		self.assertIn("tj_source_line = tj.exemption_reason", html)
		self.assertNotIn('get_value("Customer"', html)
		self.assertNotIn("is exempted from taxes", html)

	def test_the_template_and_the_helper_agree_on_exempt(self):
		"""tj.exemption_reason has to be a sentence exactly when the template
		takes its exempt branch. The two express the same test in two
		languages, so nothing but this holds them together."""
		import os
		import re

		path = os.path.normpath(os.path.join(
			os.path.dirname(__file__), "..", "..",
			"print_format", "us_sales_tax_(invoice,_dn,_cn)", "us_sales_tax_(invoice,_dn,_cn).html",
		))
		with open(path) as f:
			html = f.read()

		in_template = re.search(r"\{%\s*set is_exempt = (.+?)%\}", html).group(1)
		for field in ("taxjar_has_nexus", "taxjar_customer_taxable", "taxjar_transaction_exempt"):
			self.assertIn(field, in_template)

		from taxjar_integration.taxjar_integration.taxjar_integration import (
			_is_exempt_for_display,
			get_taxjar_print_context,
		)

		for fields in (
			{"taxjar_customer_taxable": 0},
			{"taxjar_transaction_exempt": 1},
			{},
			{"taxjar_has_nexus": 0, "taxjar_transaction_exempt": 1},
		):
			with self.subTest(**fields):
				doc = _zero_tax_doc(**fields)
				self.assertEqual(
					bool(get_taxjar_print_context(doc).exemption_reason),
					bool(_is_exempt_for_display(doc)),
				)

	def test_no_exemption_reason_without_nexus(self):
		"""Exemption only means something once there is nexus to be exempt from."""
		from taxjar_integration.taxjar_integration.taxjar_integration import get_taxjar_print_context

		doc = _zero_tax_doc(taxjar_has_nexus=0, taxjar_transaction_exempt=1)
		self.assertIsNone(get_taxjar_print_context(doc).exemption_reason)

	def test_no_calculation_gives_no_answer(self):
		from taxjar_integration.taxjar_integration.taxjar_integration import get_taxjar_print_context

		self.assertIsNone(get_taxjar_print_context(_make_doc()).zero_tax_reason)

	def test_print_context_is_a_jinja_method(self):
		from taxjar_integration import hooks

		self.assertIn(
			"taxjar_integration.taxjar_integration.taxjar_integration.get_taxjar_print_context",
			hooks.jinja["methods"],
		)


# ── Tax Breakdown: onload/before_print wiring (set_taxjar_breakdown_html) ──

class TestSetTaxjarBreakdownHtml(UnitTestCase):

	def test_onload_sets_onload_key_not_field(self):
		"""Desk form: pushed via set_onload for the client shim to copy onto
		the field, since the browser already holds its own copy of the doc."""
		tax_data = _make_us_breakdown()
		doc = _make_doc()
		_store_breakdown_data(tax_data, doc)
		set_taxjar_breakdown_html(doc, "onload")
		self.assertIsNone(doc.taxjar_breakdown_html)
		self.assertIn("Jurisdiction", doc.get_onload("_taxjar_breakdown_html"))

	def test_before_print_sets_field_directly(self):
		"""Print/PDF: assigned directly, since print rendering reads this same
		in-memory doc in the same request - no client round trip involved.
		Called as doc.run_method("before_print", print_settings) by
		frappe.www.printview - the print_settings positional arg must not
		raise a TypeError."""
		tax_data = _make_us_breakdown()
		doc = _make_doc()
		_store_breakdown_data(tax_data, doc)
		set_taxjar_breakdown_html(doc, "before_print", {"some": "print_settings"})
		self.assertIsNotNone(doc.taxjar_breakdown_html)
		self.assertIn("Jurisdiction", doc.taxjar_breakdown_html)
		self.assertEqual(doc.get_onload(), {})

	def test_noop_when_doc_has_no_breakdown_html_field(self):
		doc = _make_doc()
		doc.meta = _FakeMeta(fields=())
		set_taxjar_breakdown_html(doc, "onload")
		self.assertEqual(doc.get_onload(), {})

	def test_real_document_virtual_field_has_no_instance_attribute_when_loaded_from_db(self):
		"""Regression guard for the exact bug this class exists to prevent:
		hasattr(doc, "taxjar_breakdown_html") is False on a document loaded via
		Document.load_from_db(), because is_virtual fields with no backing
		@property are never set as instance attributes there - load_from_db
		populates BaseDocument.__init__ from a raw "SELECT *" row dict, which
		only has real DB columns, and (unlike frappe.new_doc(), which does call
		init_valid_columns() and so does NOT reproduce this) never backfills
		virtual fields to None. A guard using hasattr() instead of
		doc.meta.has_field() silently no-opped set_taxjar_breakdown_html for
		every already-saved document - exactly what onload/before_print always
		deal with.

		Reproduces that exact construction path (BaseDocument.__init__ from a
		bare dict, the same call load_from_db makes) without needing a
		persisted record, since frappe.new_doc()/frappe.get_doc({...}) both
		route through init_valid_columns() and would not reproduce the bug."""
		from frappe.model.base_document import BaseDocument
		from frappe.model.document import get_controller

		controller = get_controller("Quotation")
		doc = controller.__new__(controller)
		doc.flags = frappe._dict()
		BaseDocument.__init__(doc, {"doctype": "Quotation", "name": "QTN-TEST-0001", "company": "_Test Company"})

		self.assertTrue(doc.meta.has_field("taxjar_breakdown_html"))
		self.assertFalse(hasattr(doc, "taxjar_breakdown_html"))

	def test_onload_populates_real_document_loaded_from_db(self):
		"""End-to-end against the real onload dispatch path AND the
		load_from_db-shaped construction from the test above - together these
		cover the exact scenario that broke in production: a doc.meta.has_field()
		guard (fixed) vs. the hasattr() guard (buggy) it replaced, wired through
		the real set_onload()/__onload round trip."""
		from frappe.desk.form.load import run_onload
		from frappe.model.base_document import BaseDocument
		from frappe.model.document import get_controller

		controller = get_controller("Quotation")
		doc = controller.__new__(controller)
		doc.flags = frappe._dict()
		BaseDocument.__init__(doc, {"doctype": "Quotation", "name": "QTN-TEST-0001", "company": "_Test Company"})
		doc.items = []
		doc.append("items", {"item_code": "_Test Item", "qty": 1, "rate": 100})
		doc.taxjar_breakdown_json = frappe.as_json(_extract_breakdown_data(_make_us_breakdown(), doc))

		run_onload(doc)

		html = doc.get_onload("_taxjar_breakdown_html")
		self.assertIsNotNone(html)
		self.assertIn("Jurisdiction", html)


class TestTaxjarBreakdownHtmlHooksRegistered(UnitTestCase):
	"""onload/before_print never fire for a hook registered on the wrong key
	(e.g. a child doctype - see the child-table field investigation for why
	that matters) - so this pins the exact transaction-doctype grouping the
	hook must be registered under."""

	def _transaction_doc_events(self):
		from taxjar_integration import hooks
		for doctypes, events in hooks.doc_events.items():
			key = doctypes if isinstance(doctypes, tuple) else (doctypes,)
			if set(("Quotation", "Sales Order", "Sales Invoice")) <= set(key):
				return events
		return {}

	def test_onload_registered_on_transaction_doctypes(self):
		events = self._transaction_doc_events()
		self.assertIn("set_taxjar_breakdown_html", events.get("onload", ""))

	def test_before_print_registered_on_transaction_doctypes(self):
		events = self._transaction_doc_events()
		self.assertIn("set_taxjar_breakdown_html", events.get("before_print", ""))


