		with patch(f"{REGIONAL}.ensure_company_ledgers_and_template") as mock_ensure, \
		     patch(f"{REGIONAL}.frappe.get_single", return_value=settings):
			sync_all_company_tax_templates()

		mock_ensure.assert_not_called()


