# ── A charge prints its description only ─────────────────────────────────────


class TestChargeRowsPrintTheirDescriptionOnly(UnitTestCase):
	"""An extra charge in the US Sales Tax (Invoice, DN, CN) format totals prints one line.

	It used to print the ledger under the description as well. ERPNext fills a
	charge's description with the account name, so the two lines said the same
	thing: "Interest Income:" over "71000 - Interest Income". Rendered from
	the template file's own totals loop.
	"""

	ROW_LOOP = re.compile(r"\{%-\s*for tax in ad_hoc_rows \+ shipping_rows.*?\{%-\s*endfor\s*-%\}", re.S)

	def _html(self):
		import os

		path = os.path.normpath(os.path.join(
			os.path.dirname(__file__), "..", "..",
			"print_format", "us_sales_tax_(invoice,_dn,_cn)", "us_sales_tax_(invoice,_dn,_cn).html",
		))
		with open(path) as handle:
			return handle.read()

	def _row(self, account_head, description):
		row = frappe._dict(account_head=account_head, description=description, tax_amount=25)
		row.get_formatted = lambda fieldname, doc=None: "$25.00"
		return row

	def _printed(self, ad_hoc=(), shipping=()):
		loop = self.ROW_LOOP.search(self._html())
		self.assertIsNotNone(loop, "the totals no longer loop over ad_hoc_rows + shipping_rows")
		return frappe.render_template(loop.group(0), {
			"ad_hoc_rows": list(ad_hoc), "shipping_rows": list(shipping), "tax_rows": [], "other_rows": [],
			"shipping_head": "Freight - FI",
			"company_abbr": "FI",
			"doc": frappe._dict(taxjar_freight_taxable=1),
		})

	def test_a_charge_prints_its_description_and_not_its_ledger(self):
		html = self._printed(ad_hoc=[self._row("71000 - Interest Income - FI", "Interest Income")])
		self.assertIn("Interest Income:", html)
		self.assertNotIn("71000", html)

	def test_a_custom_description_prints_alone_too(self):
		html = self._printed(ad_hoc=[self._row("71000 - Interest Income - FI", "Late payment fee")])
		self.assertIn("Late payment fee:", html)
		self.assertNotIn("Interest Income", html)

	def test_the_shipping_row_keeps_its_taxable_note(self):
		"""Whether freight is taxed is a tax fact, not the ledger, so it stays."""
		html = self._printed(shipping=[self._row("Freight - FI", "Shipping & Forwarding Charges")])
		self.assertIn("Shipping & Forwarding:", html)
		self.assertIn("Taxable", html)


class TestCashDiscountPrintsAboveGrandTotal(UnitTestCase):
	"""A cash or non-trade discount prints its own row in the totals.

	ERPNext takes this discount off Grand Total after tax and leaves
	net_amount alone, so the item Discount column cannot show it. Without
	the row, Net Total plus the taxes does not foot to Grand Total.
	"""

	DISCOUNT_ROW = re.compile(r"\{%\s*if doc\.discount_amount.*?\{%\s*endif\s*%\}", re.S)

	def _html(self):
		import os

		path = os.path.normpath(os.path.join(
			os.path.dirname(__file__), "..", "..",
			"print_format", "us_sales_tax_(invoice,_dn,_cn)", "us_sales_tax_(invoice,_dn,_cn).html",
		))
		with open(path) as handle:
			return handle.read()

	def _printed(self, apply_discount_on="Grand Total", cash=1, discount_amount=10):
		block = self.DISCOUNT_ROW.search(self._html())
		self.assertIsNotNone(block, "the totals no longer have a discount row")
		doc = frappe._dict(
			discount_amount=discount_amount,
			apply_discount_on=apply_discount_on,
			is_cash_or_non_trade_discount=cash,
		)
		doc.get_formatted = lambda fieldname, doc=None: "$10.00"
		return frappe.render_template(block.group(0), {"doc": doc})

	def test_a_cash_discount_prints_a_discount_row(self):
		html = self._printed()
		self.assertIn("Discount:", html)
		self.assertIn("-$10.00", html)

	def test_the_row_sits_between_the_charges_and_grand_total(self):
		html = self._html()
		row = self.DISCOUNT_ROW.search(html).start()
		self.assertLess(html.index("{%- endfor -%}", html.index("ad_hoc_rows + shipping_rows")), row)
		self.assertLess(row, html.index('class="taxjar-grand-total"'))

	def test_a_trade_discount_on_grand_total_prints_no_row(self):
		"""ERPNext spreads it over net_amount, so the item column shows it."""
		self.assertNotIn("Discount:", self._printed(cash=0))

	def test_a_discount_on_net_total_prints_no_row(self):
		self.assertNotIn("Discount:", self._printed(apply_discount_on="Net Total"))

	def test_no_discount_prints_no_row(self):
		self.assertNotIn("Discount:", self._printed(discount_amount=0))


# ── The workspace roles reach every site ─────────────────────────────────────


class TestWorkspaceRoles(UnitTestCase):
	"""setup_taxjar() gives the TaxJar workspace its roles on every install and
	migrate.

	The workspace JSON carries them too, but Frappe imports that file only when
	it is newer than the site's own copy. The app saves the workspace to put
	back the guided-setup banner, and admins save it to change the layout, so on
	many sites the file is never imported and the roles never arrive.
	"""

	def _workspace(self, *roles):
		"""An unsaved Workspace, so no test writes the site's own."""
		workspace = frappe.new_doc("Workspace")
		for role in roles:
			workspace.append("roles", {"role": role})
		return workspace

	def _roles(self, workspace):
		return [row.role for row in workspace.roles]

	def _set(self, workspace, exists=True):
		from taxjar_integration import install

		with patch.object(install.frappe.db, "exists", return_value=exists), \
		     patch.object(install.frappe, "get_doc", return_value=workspace), \
		     patch.object(workspace, "save") as save:
			install.set_workspace_roles()
		return save

	def test_an_empty_roles_table_gets_the_three_persona_roles(self):
		workspace = self._workspace()
		save = self._set(workspace)

		self.assertEqual(self._roles(workspace), ["System Manager", "Accounts Manager", "Accounts User"])
		save.assert_called_once_with(ignore_permissions=True)

	def test_only_a_missing_role_is_added(self):
		workspace = self._workspace("Accounts User", "System Manager")
		self._set(workspace)

		self.assertEqual(self._roles(workspace), ["Accounts User", "System Manager", "Accounts Manager"])

	def test_a_role_an_admin_added_is_kept(self):
		workspace = self._workspace("Tax Desk")
		self._set(workspace)

		self.assertIn("Tax Desk", self._roles(workspace))
		self.assertEqual(len(self._roles(workspace)), 4)

	def test_nothing_is_saved_when_no_role_is_missing(self):
		"""Each save moves the workspace's own date forward, which is what keeps
		the JSON file out, so a save with nothing to add is avoided."""
		workspace = self._workspace("System Manager", "Accounts Manager", "Accounts User", "Tax Desk")
		self._set(workspace).assert_not_called()

	def test_a_site_without_the_workspace_is_left_alone(self):
		from taxjar_integration import install

		with patch.object(install.frappe.db, "exists", return_value=False), \
		     patch.object(install.frappe, "get_doc") as get_doc:
			install.set_workspace_roles()
		get_doc.assert_not_called()

	def test_setup_taxjar_sets_the_roles(self):
		from taxjar_integration import install

		patches = [
			patch(f"taxjar_integration.install.{name}")
			for name in (
				"make_custom_fields", "add_product_tax_categories", "sync_all_company_tax_templates",
				"hide_legacy_exempt_from_sales_tax", "set_taxes_field_description", "add_guided_setup_alert",
			)
		]
		for item in patches:
			item.start()
			self.addCleanup(item.stop)
		with patch("taxjar_integration.install.set_workspace_roles") as set_roles:
			install.setup_taxjar()
		set_roles.assert_called_once()

	def test_the_roles_are_the_ones_the_workspace_json_ships(self):
		"""Two copies of one fact: the constant the code adds, and the JSON."""
		import json
		import os

		from taxjar_integration import install

		path = os.path.join(
			os.path.dirname(__file__), "..", "..", "workspace", "taxjar_integration", "taxjar_integration.json"
		)
		with open(path) as handle:
			shipped = [row["role"] for row in json.load(handle)["roles"]]
		self.assertEqual(list(install.WORKSPACE_ROLES), shipped)


# ── A permission refusal links to the roles documentation ────────────────────


class TestPermissionRefusalLinksTheDocs(UnitTestCase):
	"""Every permission check in the app goes through require_permission(), so
	a refusal says which right is missing and links to the task table that
	lists the rights for each TaxJar task."""

	def test_a_refusal_names_the_right_and_links_the_task_table(self):
		from taxjar_integration.taxjar_integration import access

		with patch.object(access.frappe, "has_permission", return_value=False):
			with self.assertRaises(frappe.PermissionError) as ctx:
				access.require_permission("Customer", "write", doc="CUST-0001")

		message = str(ctx.exception)
		self.assertIn("Customer", message)
		self.assertIn("write", message)
		self.assertIn(f'href="{access.ROLES_DOCS_URL}#{access.TASK_TABLE_ANCHOR}"', message)
		self.assertIn("ask your administrator to update permissions for your user.", message)
		# A blank line, then the link on a line of its own, with the arrow in it.
		self.assertIn("for your user.<br><br><a ", message)
		self.assertIn("Read documentation &rarr;</a>", message)

	def test_a_user_with_the_right_passes(self):
		from taxjar_integration.taxjar_integration import access

		with patch.object(access.frappe, "has_permission", return_value=True) as has_permission:
			access.require_permission("Customer", "write", doc="CUST-0001")

		has_permission.assert_called_once_with("Customer", "write", doc="CUST-0001")

	def test_the_desk_script_knows_the_same_docs_url(self):
		"""Two copies of one fact: the URL in the refusal, and the URL the desk
		script opens in a new tab. Frappe drops target from message links."""
		import os
		import re

		from taxjar_integration.taxjar_integration import access

		path = os.path.join(frappe.get_app_path("taxjar_integration"), "public", "js", "taxjar_utils.js")
		with open(path) as handle:
			match = re.search(r'taxjar_integration\.ROLES_DOCS_URL = "([^"]+)";', handle.read())
		self.assertIsNotNone(match, "taxjar_utils.js no longer sets taxjar_integration.ROLES_DOCS_URL")
		self.assertEqual(match.group(1), access.ROLES_DOCS_URL)

	def test_the_anchor_is_the_task_table_heading(self):
		"""The heading in docs/taxjar/09-roles-and-permissions.md, as a slug."""
		from taxjar_integration.taxjar_integration import access

		self.assertEqual(access.TASK_TABLE_ANCHOR, "taxjar-tasks-and-the-rights-they-need")

	def test_no_check_throws_frappes_own_message(self):
		"""frappe.has_permission(..., throw=True) raises with Frappe's text, which
		has no link. A check written that way would skip the docs."""
		import os

		root = os.path.dirname(frappe.get_module_path("taxjar_integration"))
		offenders = []
		for folder, _dirs, files in os.walk(root):
			for name in files:
				if not name.endswith(".py") or name.startswith("test_"):
					continue
				with open(os.path.join(folder, name)) as handle:
					for number, line in enumerate(handle, 1):
						if "has_permission(" in line and "throw=True" in line:
							offenders.append(f"{name}:{number}")
		self.assertEqual(offenders, [])


# ── Endpoints nothing called are gone ────────────────────────────────────────


class TestUncalledEndpointsAreGone(UnitTestCase):
	"""Every whitelisted function can be called at /api/method/ by any logged-in
	user, whether or not a screen calls it. These three had no caller:

	- fetch_transaction_from_taxjar: nothing reads transactions back from TaxJar.
	- delete_transaction_manual: deleted an order or refund in TaxJar while the
	  invoice stayed submitted. Cancelling the invoice deletes it in TaxJar.
	- verify_address_with_taxjar: TaxJar Setup verifies the company address
	  through verify_company_address(), which needs write on TaxJar Settings.
	"""

	def test_they_no_longer_exist(self):
		from taxjar_integration.taxjar_integration import taxjar_integration as mod

		for name in ("fetch_transaction_from_taxjar", "delete_transaction_manual", "verify_address_with_taxjar"):
			with self.subTest(name=name):
				self.assertFalse(hasattr(mod, name))

	def test_the_address_check_they_shared_stays(self):
		"""verify_company_address() still uses it."""
		from taxjar_integration.taxjar_integration import taxjar_integration as mod

		self.assertTrue(callable(mod._validate_address_with_taxjar))


class TestDefaultPrintFormat(UnitTestCase):
	"""The app's print format becomes the Sales Invoice default, but only where
	Sales Invoice has no default yet. Its old name, "US Sales Tax Invoice", is
	renamed before the model sync."""

	def _set(self, default=None, format_exists=True):
		from taxjar_integration import install

		meta = MagicMock(default_print_format=default)
		with patch.object(install.frappe, "get_meta", return_value=meta), \
		     patch.object(install.frappe.db, "exists", return_value=format_exists), \
		     patch.object(install.frappe, "get_doc") as get_doc, \
		     patch.object(install.frappe, "clear_cache"):
			install.set_default_print_format()
		return get_doc

	def test_an_empty_default_gets_the_app_format(self):
		from taxjar_integration import install

		get_doc = self._set()

		row = get_doc.call_args.args[0]
		self.assertEqual(row["doctype"], "Property Setter")
		self.assertEqual(row["doctype_or_field"], "DocType")
		self.assertEqual(row["doc_type"], "Sales Invoice")
		self.assertEqual(row["property"], "default_print_format")
		self.assertEqual(row["value"], install.PRINT_FORMAT)
		get_doc.return_value.insert.assert_called_once_with(ignore_permissions=True)

	def test_the_row_names_the_app_module(self):
		"""Frappe ignores the row while the app is disabled, and deletes it when
		the app is uninstalled, together with the print format it names."""
		row = self._set().call_args.args[0]
		self.assertEqual(row["module"], "TaxJar Integration")

	def test_a_default_the_site_chose_stays(self):
		self._set(default="Sales Invoice with Item Image").assert_not_called()

	def test_nothing_is_set_when_the_format_is_missing(self):
		self._set(format_exists=False).assert_not_called()

	def test_install_sets_the_default_and_migrate_does_not(self):
		"""A site that clears the default later keeps it clear."""
		import inspect

		from taxjar_integration import install

		self.assertIn("set_default_print_format()", inspect.getsource(install.after_install))
		self.assertNotIn("set_default_print_format", inspect.getsource(install.after_migrate))
		self.assertNotIn("set_default_print_format", inspect.getsource(install.setup_taxjar))

	def test_the_files_carry_the_new_name(self):
		"""Frappe finds a standard print format by the scrubbed name, so the
		folder, the files and the include path must all follow it."""
		import os

		from taxjar_integration import install

		folder = frappe.scrub(install.PRINT_FORMAT)
		base = os.path.normpath(os.path.join(os.path.dirname(__file__), "..", "..", "print_format", folder))
		with open(os.path.join(base, f"{folder}.json")) as f:
			self.assertEqual(json.load(f)["name"], install.PRINT_FORMAT)
		with open(os.path.join(base, f"{folder}.html")) as f:
			self.assertIn(f"print_format/{folder}/{folder}.css", f.read())
		self.assertTrue(os.path.exists(os.path.join(base, f"{folder}.css")))

	def test_the_rename_runs_before_the_model_sync(self):
		"""After the sync, the new JSON would make a second record and leave
		the old one with no files."""
		import os

		path = os.path.join(frappe.get_app_path("taxjar_integration"), "patches.txt")
		with open(path) as f:
			pre, post = f.read().split("[post_model_sync]")
		self.assertIn("taxjar_integration.patches.rename_us_sales_tax_print_format", pre)
		self.assertIn("taxjar_integration.patches.set_default_print_format", post)

	def _rename(self, old_exists, new_exists):
		from taxjar_integration.patches import rename_us_sales_tax_print_format as patch_module

		names = {"US Sales Tax Invoice": old_exists, "US Sales Tax (Invoice, DN, CN)": new_exists}
		with patch.object(patch_module.frappe.db, "exists", side_effect=lambda dt, name: names[name]), \
		     patch.object(patch_module.frappe, "rename_doc") as rename_doc, \
		     patch.object(patch_module.frappe, "delete_doc") as delete_doc:
			patch_module.execute()
		return rename_doc, delete_doc

	def test_the_old_format_is_renamed(self):
		rename_doc, delete_doc = self._rename(old_exists=True, new_exists=False)
		rename_doc.assert_called_once_with(
			"Print Format", "US Sales Tax Invoice", "US Sales Tax (Invoice, DN, CN)", force=True
		)
		delete_doc.assert_not_called()

	def test_an_old_format_beside_the_new_one_is_deleted(self):
		rename_doc, delete_doc = self._rename(old_exists=True, new_exists=True)
		rename_doc.assert_not_called()
		delete_doc.assert_called_once_with(
			"Print Format", "US Sales Tax Invoice", ignore_missing=True, force=True
		)

	def test_a_site_without_the_old_format_is_left_alone(self):
		rename_doc, delete_doc = self._rename(old_exists=False, new_exists=True)
		rename_doc.assert_not_called()
		delete_doc.assert_not_called()


class TestDefaultLetterHead(UnitTestCase):
	"""The app ships "US Company Letter Head" and makes it the site's default
	letter head for documents, but only where no letter head is the default.
	It runs on every migrate, so it must never stop one."""

	def _set(self, default_exists=False, letter_head_exists=True, has_scope_field=True, exists_error=None):
		from taxjar_integration import install

		def exists(doctype, filters):
			if exists_error:
				raise exists_error
			return letter_head_exists if filters.get("name") == install.LETTER_HEAD else default_exists

		meta = MagicMock()
		meta.has_field.return_value = has_scope_field
		with patch.object(install.frappe.db, "exists", side_effect=exists) as exists_mock, \
		     patch.object(install.frappe, "get_meta", return_value=meta), \
		     patch.object(install.frappe.db, "set_value", autospec=True) as set_value, \
		     patch.object(install.frappe.db, "get_value", return_value="<table/>"), \
		     patch.object(install.frappe.db, "set_default", autospec=True) as set_default, \
		     patch.object(install.frappe.db, "savepoint", autospec=True) as savepoint, \
		     patch.object(install.frappe.db, "rollback", autospec=True) as rollback, \
		     patch.object(install.frappe.db, "release_savepoint", autospec=True) as release, \
		     patch.object(install.frappe, "log_error") as log_error, \
		     patch.object(install.frappe, "clear_cache"):
			install.set_default_letter_head()
		return frappe._dict(
			exists=exists_mock, set_value=set_value, set_default=set_default, savepoint=savepoint,
			rollback=rollback, release=release, log_error=log_error,
		)

	def _json(self):
		import os

		from taxjar_integration import install

		folder = frappe.scrub(install.LETTER_HEAD)
		path = os.path.join(frappe.get_module_path("TaxJar Integration"), "letter_head", folder, f"{folder}.json")
		with open(path) as f:
			return json.load(f)

	def test_an_empty_default_gets_the_app_letter_head(self):
		from taxjar_integration import install

		run = self._set()

		run.set_value.assert_any_call("Letter Head", install.LETTER_HEAD, "is_default", 1, update_modified=False)
		run.set_default.assert_has_calls([
			call("letter_head", install.LETTER_HEAD),
			call("default_letter_head_content", "<table/>"),
		])
		run.release.assert_called_once_with(install.LETTER_HEAD_SAVEPOINT)
		run.log_error.assert_not_called()

	def test_the_flag_is_cleared_on_every_other_document_letter_head(self):
		"""A disabled row can still carry is_default. A normal save clears the
		others the same way."""
		from taxjar_integration import install

		run = self._set()

		run.set_value.assert_any_call(
			"Letter Head", {"name": ["!=", install.LETTER_HEAD], "letter_head_for": "DocType"},
			"is_default", 0, update_modified=False,
		)

	def test_a_default_the_site_chose_stays(self):
		run = self._set(default_exists=True)
		run.set_value.assert_not_called()
		run.set_default.assert_not_called()

	def test_nothing_is_set_when_the_letter_head_is_missing_or_disabled(self):
		run = self._set(letter_head_exists=False)
		run.set_value.assert_not_called()
		run.set_default.assert_not_called()

	def test_a_frappe_without_letter_head_for_reads_every_letter_head(self):
		run = self._set(has_scope_field=False)
		for c in run.exists.call_args_list:
			self.assertNotIn("letter_head_for", c.args[1])
		for c in run.set_value.call_args_list:
			if isinstance(c.args[1], dict):
				self.assertNotIn("letter_head_for", c.args[1])

	def test_an_error_is_logged_and_never_stops_the_migrate(self):
		"""Only this function's writes are undone, through its own savepoint -
		not the rest of the migrate's transaction."""
		from taxjar_integration import install

		run = self._set(exists_error=frappe.db.InternalError("table locked"))

		run.rollback.assert_called_once_with(save_point=install.LETTER_HEAD_SAVEPOINT)
		run.log_error.assert_called_once()
		run.release.assert_not_called()
		run.set_value.assert_not_called()

	def test_on_the_real_database(self):
		"""No mocks: the real queries, run inside a savepoint that is rolled
		back, so the site keeps its own default."""
		from taxjar_integration import install

		if not frappe.db.exists("Letter Head", install.LETTER_HEAD):
			self.skipTest("the app's letter head is not imported on this site")

		frappe.db.savepoint("test_default_letter_head")
		try:
			frappe.db.set_value("Letter Head", {"name": ["is", "set"]}, "is_default", 0, update_modified=False)
			install.set_default_letter_head()

			defaults = frappe.get_all(
				"Letter Head", filters={"is_default": 1, "letter_head_for": "DocType"}, pluck="name"
			)
			self.assertEqual(defaults, [install.LETTER_HEAD])
			self.assertEqual(frappe.db.get_default("letter_head"), install.LETTER_HEAD)

			# A second run - the next migrate - changes nothing.
			install.set_default_letter_head()
			defaults = frappe.get_all(
				"Letter Head", filters={"is_default": 1, "letter_head_for": "DocType"}, pluck="name"
			)
			self.assertEqual(defaults, [install.LETTER_HEAD])
		finally:
			frappe.db.rollback(save_point="test_default_letter_head")
			frappe.clear_cache()

	def test_install_and_migrate_both_set_the_default(self):
		"""An update to the JSON resets is_default on import, so migrate sets
		it back."""
		import inspect

		from taxjar_integration import install

		self.assertIn("set_default_letter_head()", inspect.getsource(install.after_install))
		self.assertIn("set_default_letter_head()", inspect.getsource(install.after_migrate))

	def test_the_file_is_a_standard_letter_head_of_this_app(self):
		"""Standard and in this app's module, so Frappe imports it on migrate
		and deletes it when the app is uninstalled. Not the default in the file:
		set_default_letter_head() decides that on the site."""
		from taxjar_integration import install

		doc = self._json()
		self.assertEqual(doc["name"], install.LETTER_HEAD)
		self.assertEqual(doc["letter_head_name"], install.LETTER_HEAD)
		self.assertEqual(doc["module"], "TaxJar Integration")
		self.assertEqual(doc["standard"], "Yes")
		self.assertEqual(doc["letter_head_for"], "DocType")
		self.assertEqual(doc["is_default"], 0)
		self.assertEqual(doc["disabled"], 0)

	def test_the_header_prints_no_document_type_or_number(self):
		"""Each print format prints its own title and number."""
		content = self._json()["content"]
		self.assertNotIn("doc.doctype", content)
		self.assertNotIn("doc.name", content)
		self.assertIn("company_logo", content)
		self.assertIn("company_address", content)

	def test_the_header_renders_the_company_block(self):
		doc = frappe._dict(doctype="Sales Invoice", name="ACC-SINV-0001", company=None)
		html = frappe.render_template(self._json()["content"], {"doc": doc})
		self.assertNotIn("Sales Invoice", html)
		self.assertNotIn("ACC-SINV-0001", html)
		self.assertIn("letterhead-container", html)
